-- New sample post demonstrating the full Template bai SEO.docx structure end to end:
-- primary/secondary keyword, meta description (120-150 chars), sapo (80-100 words with the
-- primary keyword + a VIBEU CTA), an H2 section with two H3 subsections (150-200 words each),
-- an inline image block between sections (caption carries the primary keyword), a second H2
-- section (no H3, under 500 words), and a closing paragraph with keyword + brand + CTA.
--
-- Reuses two of the site's existing AI-generated stock photos (see
-- public/assets/blog/SOURCES.md) for the cover and the inline image, since this session has no
-- way to source or upload a brand-new photo — swap in real photography before treating this as
-- permanent published content. Idempotent: safe to re-run (upsert on slug).
insert into public.blog_posts (
  id, slug, title, category, excerpt, content, content_blocks, meta_description,
  primary_keyword, secondary_keyword, accent_color, cover_src, cover_alt, published, read_minutes
) values (
  '77432ec0-b9fa-4166-9c46-8e49386a4138',
  'phoi-mau-nail-theo-mua',
  'Phối màu nail theo mùa: 4 bảng màu không bao giờ lỗi thời',
  'tips',
  'Bạn có để ý rằng cùng một màu sơn nhưng lên tay lại "sai sai" vào những thời điểm khác nhau trong năm? Phối màu nail theo mùa liên quan tới ánh sáng, trang phục và tâm trạng theo từng mùa trong năm. Từ pastel nhẹ nhàng của mùa xuân đến sắc nâu ấm áp của mùa thu, mỗi mùa đều có một bảng màu "ăn ảnh" riêng. VIBEU gợi ý 4 bảng màu theo mùa để bạn không còn băn khoăn nên sơn màu gì — thử ngay trên Nail Studio trước khi ra tiệm.',
  array['4 bảng màu nail theo mùa được yêu thích nhất', 'Mỗi mùa trong năm mang một "vibe" ánh sáng và tông màu chủ đạo khác nhau — và bộ móng tay chính là phụ kiện nhỏ nhưng "tố cáo" rõ nhất gu thẩm mỹ theo mùa của bạn. Một màu cam cháy rực rỡ có thể cực kỳ nổi bật dưới nắng hè nhưng lại hơi lạc quẻ giữa tiết trời se lạnh cuối năm. Ngược lại, những tông nâu trầm ấm áp tuy sang trọng vào mùa đông nhưng lại dễ khiến bàn tay trông nặng nề nếu diện vào giữa mùa hè oi ả. Nắm được quy tắc phối màu nail theo mùa không có nghĩa là bạn phải tuân theo cứng nhắc, mà giúp bạn có điểm khởi đầu chắc chắn trước khi biến tấu theo phong cách riêng.', 'Bảng màu Xuân – Hạ: Tươi sáng và tràn năng lượng', 'Mùa xuân và mùa hè là thời điểm lý tưởng để thử nghiệm những gam màu tươi sáng, độ bão hoà cao. Pastel kem dâu, xanh mint, vàng chanh hay cam san hô đều là những lựa chọn kinh điển không bao giờ lỗi mốt trong giai đoạn này, đặc biệt hợp với các hoạt động ngoài trời như đi biển, dã ngoại hay dự tiệc cưới ban ngày. Nếu muốn nổi bật hơn, bạn có thể thử hiệu ứng Sơn thạch (Jelly) trong suốt phối cùng charm hoa quả hoặc charm bướm nhỏ xinh — vừa mát mắt vừa rất "hè". Với những bạn thích sự tinh tế hơn, gam màu be hồng (nude pink) pha chút ánh nhũ bạc cũng là gợi ý an toàn nhưng vẫn đủ tươi tắn cho mùa xuân. Trong Thư viện mẫu của VIBEU, bạn có thể lọc theo thẻ mùa để tham khảo nhanh những bộ màu đang được cộng đồng yêu thích nhất trong giai đoạn Xuân – Hạ.', 'Bảng màu Thu – Đông: Ấm áp và sang trọng', 'Khi thời tiết chuyển lạnh, bảng màu nail cũng nên "ấm" lên theo đúng nghĩa đen. Các tông nâu caramel, cam đất, đỏ rượu vang hay xanh rêu đậm là những gợi ý kinh điển giúp bàn tay trông sang trọng, hợp với trang phục len dạ và áo khoác dày của mùa thu đông. Hiệu ứng Chrome ánh kim hoặc Velvet nhung mờ cũng đặc biệt hợp trong giai đoạn này, mang lại cảm giác ấm áp, có chiều sâu hơn so với lớp sơn Gel bóng thông thường của mùa hè. Nếu có dịp lễ cuối năm, bạn hoàn toàn có thể nâng cấp bảng màu ấm này bằng cách đính thêm charm ngôi sao hoặc charm kim tuyến ở 1-2 ngón điểm nhấn để tăng độ lấp lánh mà không bị quá tay. Đây cũng là khoảng thời gian các mẫu nail chủ đề lễ hội trong Thư viện mẫu VIBEU được lưu nhiều nhất trong năm.', 'Mẹo chọn màu nail hợp mùa mà không lỗi thời', 'Phối màu nail theo mùa không có nghĩa là bạn phải bỏ hẳn những màu yêu thích chỉ vì chúng không "đúng mùa". Một mẹo đơn giản là giữ nguyên tông màu gốc nhưng thay đổi hiệu ứng bề mặt: cùng một màu hồng, phiên bản Sơn thạch trong veo sẽ hợp mùa hè hơn trong khi phiên bản Chrome ánh kim hoặc Glazed bóng gương lại hợp mùa đông hơn hẳn. Cách làm này giúp bạn "tái sử dụng" bảng màu quen thuộc quanh năm mà vẫn luôn cảm giác mới mẻ, hợp thời điểm.', 'Một yếu tố khác cũng quan trọng không kém là tông da tay. Da ấm thường hợp với các gam màu đất, cam, nâu ở mọi mùa, trong khi da sáng/trung tính có thể linh hoạt hơn với cả tông lạnh lẫn tông ấm. Thay vì đoán mò, bạn có thể vào Nail Studio, chọn đúng tông da mô phỏng gần với mình nhất rồi thử trực tiếp từng bảng màu theo mùa lên bàn tay ảo — nhìn thấy trước kết quả sẽ giúp bạn tự tin hơn hẳn khi ra tiệm.', 'Cuối cùng, đừng ngại kết hợp nhiều mùa trong cùng một bộ nail nếu bạn thực sự thích — ví dụ nền màu ấm mùa thu nhưng đính charm hoa nhỏ xinh mang hơi hướng mùa xuân. Quy tắc phối màu theo mùa nên là điểm tựa để bạn sáng tạo tự tin hơn, không phải khuôn khổ bắt buộc phải tuân theo.', 'Phối màu nail theo mùa thực chất không hề phức tạp nếu bạn nắm được bảng màu chủ đạo của từng thời điểm trong năm và biết cách biến tấu theo gu riêng. Ghé Nail Studio của VIBEU ngay hôm nay để thử trực tiếp các gợi ý màu theo mùa lên mô phỏng bàn tay, tinh chỉnh charm và hiệu ứng theo đúng ý thích, rồi xuất công thức mang ra tiệm hoàn toàn miễn phí.'],
